<?php

declare(strict_types=1);

use PortLibs\Pandoc\AstNode;
use PortLibs\Pandoc\DocxOpenXmlReader;
use PortLibs\Pandoc\MarkdownWriter;
use PortLibs\Pandoc\WordPressBlockWriter;
use PortLibs\Pandoc\ZipPackage;

return [
    'maps docx core properties styles hyperlinks numbering and media from package parts' => static function (TestRunner $t): void {
        $document = (new DocxOpenXmlReader())->readPackage(docx_openxml_reader_fixture_parts());

        $meta = $document->attr('meta');
        $docx = $document->attr('docx');
        $heading = $document->children[0];
        $paragraph = $document->children[1];
        $ordered = $document->children[2];
        $bullet = $document->children[3];
        $imageParagraph = $document->children[4];
        $table = $document->children[5];

        $t->same('Imported DOCX Batch', $meta['title']);
        $t->same(['Migration Editor'], $meta['authors']);
        $t->same('word/document.xml', $docx['documentPart']);
        $t->same('application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml', $docx['contentTypes']['overrides']['word/document.xml']);
        $t->same('docProps/core.xml', $docx['corePropertiesPart']);
        $t->same('word/styles.xml', $docx['stylesPart']);
        $t->same('rCore', $docx['corePropertiesRelationship']['id']);
        $t->same('docProps/core.xml', $docx['corePropertiesRelationship']['targetPart']);
        $t->true(!isset($docx['stylesRelationship']), 'conventional DOCX styles fallback should not invent relationship metadata');
        $t->same('word/numbering.xml', $docx['numberingPart']);
        $t->true(!isset($docx['numberingRelationship']), 'conventional DOCX numbering fallback should not invent relationship metadata');
        $t->same('image/png', $docx['media']['word/media/review.png']['contentType']);
        $t->same(strlen('fake png bytes'), $docx['media']['word/media/review.png']['size']);

        $t->same('heading', $heading->type);
        $t->same(1, $heading->attr('level'));
        $t->same('imported-docx-heading', $heading->attr('id'));
        $t->same('Heading 1', $heading->attr('docxStyleName'));
        $t->same('strong', $paragraph->children[1]->type);
        $t->same('emph', $paragraph->children[3]->type);
        $t->same('underline', $paragraph->children[5]->type);
        $t->same('strikeout', $paragraph->children[7]->type);
        $t->same('superscript', $paragraph->children[9]->type);
        $t->same('link', $paragraph->children[11]->type);
        $t->same('https://example.test/source?post=42', $paragraph->children[11]->attr('url'));
        $t->same('rLink', $paragraph->children[11]->attr('relationshipId'));

        $t->same('ordered_list', $ordered->type);
        $t->same(3, $ordered->attr('start'));
        $t->same('upper_roman', $ordered->attr('style'));
        $t->same('one_paren', $ordered->attr('delimiter'));
        $t->same('First review step', $ordered->children[0]->children[0]->attr('text'));
        $t->same('Second review step', $ordered->children[1]->children[0]->attr('text'));
        $t->same('bullet_list', $bullet->type);
        $t->same('•', $bullet->attr('bulletChar'));
        $t->same('Bullet media note', $bullet->children[0]->children[0]->attr('text'));

        $image = $imageParagraph->children[1];
        $t->same('image', $image->type);
        $t->same('word/media/review.png', $image->attr('url'));
        $t->same('Review screenshot', $image->attr('alt'));
        $t->same('Review image', $image->attr('title'));
        $t->same('image/png', $image->attr('contentType'));
        $t->same('table', $table->type);
        $t->same('Reviewer', $table->children[0]->children[0]->children[0]->attr('text'));
        $t->same(2, $table->children[0]->children[0]->children[1]->attr('colspan'));
    },
    'normalizes docx drawing image target suffixes while preserving package provenance' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['word/_rels/document.xml.rels'] = str_replace(
            'Target="media/review.png"',
            'Target="media/review.png?display=preview#inline"',
            $parts['word/_rels/document.xml.rels']
        );

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $docx = $document->attr('docx');
        $image = $document->children[4]->children[1];
        $relationship = $docx['packageProvenance']['relationshipParts']['word/_rels/document.xml.rels']['relationships']['rImage'];
        $markdown = (new MarkdownWriter())->write($document);
        $blocks = (new WordPressBlockWriter())->write($document);

        $t->same('word/media/review.png', $image->attr('url'));
        $t->same('word/media/review.png', $image->attr('mediaPath'));
        $t->same('media/review.png?display=preview#inline', $image->attr('target'));
        $t->same('word/media/review.png?display=preview#inline', $image->attr('resolvedTarget'));
        $t->same('word/media/review.png', $image->attr('targetPart'));
        $t->same('display=preview', $image->attr('targetQuery'));
        $t->same('inline', $image->attr('targetFragment'));
        $t->same('?display=preview#inline', $image->attr('targetReferenceSuffix'));
        $t->same('image/png', $image->attr('contentType'));
        $t->same(strlen('fake png bytes'), $docx['media']['word/media/review.png']['size']);

        $t->same('media/review.png?display=preview#inline', $relationship['target']);
        $t->same('word/media/review.png?display=preview#inline', $relationship['resolvedTarget']);
        $t->same('word/media/review.png', $relationship['targetPart']);
        $t->same('display=preview', $relationship['targetQuery']);
        $t->same('inline', $relationship['targetFragment']);
        $t->same('?display=preview#inline', $relationship['targetReferenceSuffix']);
        $t->contains('![Review screenshot](word/media/review.png "Review image")', $markdown);
        $t->contains('<img src="word/media/review.png" alt="Review screenshot" title="Review image"/>', $blocks);
    },
    'exposes docx package content type relationship and part inventory provenance' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Override PartName="/customXml/item1.xml" ContentType="application/xml"/>' . "\n" .
            '  <Override PartName="/word/missing-comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['_rels/.rels'] = str_replace(
            'Target="word/document.xml"',
            'Target="word/document.xml?doc=main#body"',
            $parts['_rels/.rels']
        );
        $parts['word/_rels/document.xml.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rCustomXml" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/customXml" Target="../customXml/item1.xml?slot=1#payload"/>' . "\n" .
            '  <Relationship Id="rRemote" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="https://example.test/reference.xml?x=1#frag" TargetMode="External"/>' . "\n" .
            '</Relationships>',
            $parts['word/_rels/document.xml.rels']
        );
        $parts['customXml/item1.xml'] = '<root/>';

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $package = $document->attr('docx')['packageProvenance'];
        $contentTypesPart = $package['contentTypesPart'];
        $rootRelationshipsPart = $package['relationshipParts']['_rels/.rels'];
        $documentRelationshipsPart = $package['relationshipParts']['word/_rels/document.xml.rels'];
        $customXmlRelationship = $documentRelationshipsPart['relationships']['rCustomXml'];
        $remoteRelationship = $documentRelationshipsPart['relationships']['rRemote'];
        $inventory = $package['parts'];

        $t->same('[Content_Types].xml', $contentTypesPart['partName']);
        $t->same(true, $contentTypesPart['exists']);
        $t->same(strlen($parts['[Content_Types].xml']), $contentTypesPart['bytes']);
        $t->same('application/xml', $contentTypesPart['defaults']['xml']['contentType']);
        $t->same('application/xml', $contentTypesPart['overrides']['customXml/item1.xml']['contentType']);
        $t->same(true, $contentTypesPart['overrides']['customXml/item1.xml']['exists']);
        $t->same(false, $contentTypesPart['overrides']['word/missing-comments.xml']['exists']);

        $t->same('word/document.xml', $package['documentPart']);
        $t->same('/', $rootRelationshipsPart['sourcePart']);
        $t->same(true, $rootRelationshipsPart['exists']);
        $t->same('word/document.xml?doc=main#body', $rootRelationshipsPart['relationships']['rDoc']['resolvedTarget']);
        $t->same('word/document.xml', $rootRelationshipsPart['relationships']['rDoc']['targetPart']);
        $t->same('?doc=main#body', $rootRelationshipsPart['relationships']['rDoc']['targetReferenceSuffix']);
        $t->same(true, $rootRelationshipsPart['relationships']['rDoc']['exists']);
        $t->same('override', $rootRelationshipsPart['relationships']['rDoc']['contentTypeSource']);
        $t->same('word/document.xml', $documentRelationshipsPart['sourcePart']);
        $t->same(true, $documentRelationshipsPart['exists']);
        $t->same(4, $documentRelationshipsPart['relationshipCount']);
        $t->same('customXml/item1.xml?slot=1#payload', $customXmlRelationship['resolvedTarget']);
        $t->same('customXml/item1.xml', $customXmlRelationship['targetPart']);
        $t->same('?slot=1#payload', $customXmlRelationship['targetReferenceSuffix']);
        $t->same('slot=1', $customXmlRelationship['targetQuery']);
        $t->same('payload', $customXmlRelationship['targetFragment']);
        $t->same(true, $customXmlRelationship['exists']);
        $t->same('override', $customXmlRelationship['contentTypeSource']);
        $t->same(true, $remoteRelationship['external']);
        $t->same(null, $remoteRelationship['targetPart']);
        $t->same('x=1', $remoteRelationship['targetQuery']);
        $t->same('frag', $remoteRelationship['targetFragment']);
        $t->same('?x=1#frag', $remoteRelationship['targetReferenceSuffix']);
        $t->same(false, $remoteRelationship['exists']);

        $t->same('office-document', $inventory['word/document.xml']['roles'][0]);
        $t->true(in_array('root-relationship-target', $inventory['word/document.xml']['roles'], true), 'document root relationship role missing');
        $t->same('word/document.xml', $inventory['word/_rels/document.xml.rels']['relationshipSourcePart']);
        $t->same(true, $inventory['word/_rels/document.xml.rels']['isRelationshipPart']);
        $t->same('default', $inventory['word/_rels/document.xml.rels']['contentTypeSource']);
        $t->true(in_array('document-relationship-target', $inventory['customXml/item1.xml']['roles'], true), 'custom XML relationship role missing');
        $t->same('override', $inventory['customXml/item1.xml']['contentTypeSource']);
        $t->same('package-part', $inventory['word/styles.xml']['roles'][0]);
    },
    'labels docx relationship target package parts with semantic inventory roles' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>' . "\n" .
            '  <Override PartName="/docProps/custom.xml" ContentType="application/vnd.openxmlformats-officedocument.custom-properties+xml"/>' . "\n" .
            '  <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>' . "\n" .
            '  <Override PartName="/word/numbering.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml"/>' . "\n" .
            '  <Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/>' . "\n" .
            '  <Override PartName="/word/webSettings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.websettings+xml"/>' . "\n" .
            '  <Override PartName="/word/fontTable.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.fonttable+xml"/>' . "\n" .
            '  <Override PartName="/word/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>' . "\n" .
            '  <Override PartName="/_xmlsignatures/origin.sigs" ContentType="application/vnd.openxmlformats-package.digital-signature-origin"/>' . "\n" .
            '  <Override PartName="/_xmlsignatures/sig1.xml" ContentType="application/vnd.openxmlformats-package.digital-signature-xmlsignature+xml"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['_rels/.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rExtendedProps" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>' . "\n" .
            '  <Relationship Id="rCustomProps" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties" Target="docProps/custom.xml"/>' . "\n" .
            '  <Relationship Id="rThumbnail" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/thumbnail" Target="docProps/thumbnail.png"/>' . "\n" .
            '  <Relationship Id="rSignatureOrigin" Type="http://schemas.openxmlformats.org/package/2006/relationships/digital-signature/origin" Target="_xmlsignatures/origin.sigs"/>' . "\n" .
            '</Relationships>',
            $parts['_rels/.rels']
        );
        $parts['word/_rels/document.xml.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>' . "\n" .
            '  <Relationship Id="rNumbering" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering" Target="numbering.xml"/>' . "\n" .
            '  <Relationship Id="rSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>' . "\n" .
            '  <Relationship Id="rWebSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/webSettings" Target="webSettings.xml"/>' . "\n" .
            '  <Relationship Id="rFontTable" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/fontTable" Target="fontTable.xml"/>' . "\n" .
            '  <Relationship Id="rTheme" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="theme/theme1.xml"/>' . "\n" .
            '</Relationships>',
            $parts['word/_rels/document.xml.rels']
        );
        $parts['docProps/app.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties">
  <Application>Port Libs</Application>
</Properties>
XML;
        $parts['docProps/custom.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"/>
XML;
        $parts['docProps/thumbnail.png'] = 'thumbnail bytes';
        $parts['word/settings.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:zoom w:percent="125"/>
</w:settings>
XML;
        $parts['word/webSettings.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<w:webSettings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:allowPNG/>
</w:webSettings>
XML;
        $parts['word/fontTable.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<w:fonts xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:font w:name="Review Sans"/>
</w:fonts>
XML;
        $parts['word/theme/theme1.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Review Theme">
  <a:themeElements>
    <a:clrScheme name="Review"><a:dk1><a:srgbClr val="000000"/></a:dk1></a:clrScheme>
    <a:fontScheme name="Review"><a:majorFont><a:latin typeface="Aptos"/></a:majorFont><a:minorFont><a:latin typeface="Aptos"/></a:minorFont></a:fontScheme>
    <a:fmtScheme name="Review"/>
  </a:themeElements>
</a:theme>
XML;
        $parts['_xmlsignatures/origin.sigs'] = '';
        $parts['_xmlsignatures/_rels/origin.sigs.rels'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rSignature" Type="http://schemas.openxmlformats.org/package/2006/relationships/digital-signature/signature" Target="sig1.xml"/>
</Relationships>
XML;
        $parts['_xmlsignatures/sig1.xml'] = <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<Signature xmlns="http://www.w3.org/2000/09/xmldsig#">
  <SignedInfo><Reference URI="/word/document.xml"/></SignedInfo>
  <SignatureValue>review-signature</SignatureValue>
</Signature>
XML;

        $package = (new DocxOpenXmlReader())->readPackage($parts)->attr('docx')['packageProvenance'];
        $inventory = $package['parts'];
        $relationshipTypes = $package['relationshipTypes'];
        $expectedRoles = [
            'docProps/core.xml' => 'core-properties',
            'docProps/app.xml' => 'extended-properties',
            'docProps/custom.xml' => 'custom-properties',
            'word/styles.xml' => 'styles',
            'word/numbering.xml' => 'numbering',
            'word/settings.xml' => 'settings',
            'word/webSettings.xml' => 'web-settings',
            'word/fontTable.xml' => 'font-table',
            'word/theme/theme1.xml' => 'theme',
            'docProps/thumbnail.png' => 'package-thumbnail',
            '_xmlsignatures/origin.sigs' => 'digital-signature-origin',
            '_xmlsignatures/sig1.xml' => 'digital-signature-signature',
        ];
        $relationshipTypeRoles = [
            'http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties' => 'core-properties',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties' => 'extended-properties',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties' => 'custom-properties',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles' => 'styles',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering' => 'numbering',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings' => 'settings',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/webSettings' => 'web-settings',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/fontTable' => 'font-table',
            'http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme' => 'theme',
            'http://schemas.openxmlformats.org/package/2006/relationships/metadata/thumbnail' => 'package-thumbnail',
            'http://schemas.openxmlformats.org/package/2006/relationships/digital-signature/origin' => 'digital-signature-origin',
            'http://schemas.openxmlformats.org/package/2006/relationships/digital-signature/signature' => 'digital-signature-signature',
        ];

        foreach ($expectedRoles as $partName => $role) {
            $t->true(in_array($role, $inventory[$partName]['roles'], true), "{$partName} inventory role missing {$role}");
        }
        foreach ($relationshipTypeRoles as $relationshipType => $role) {
            $t->same(1, $relationshipTypes[$relationshipType]['targetRoleCounts'][$role] ?? 0);
        }

        $t->same('relationship', $package['selectedXmlParts']['byKind']['styles']['selectionSource']);
        $t->same('relationship', $package['selectedXmlParts']['byKind']['numbering']['selectionSource']);
        $t->same('relationship', $package['selectedXmlParts']['byKind']['webSettings']['selectionSource']);
        $t->same(1, $package['summary']['packageThumbnailReadableCount']);
        $t->same(1, $package['summary']['digitalSignatureOriginCount']);
        $t->same(1, $package['summary']['digitalSignatureSignatureCount']);
    },
    'surfaces docx encrypted package relationships as metadata only provenance' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $encryptedRelationshipType = 'http://schemas.openxmlformats.org/package/2006/relationships/encrypted-package';
        $encryptedContentType = 'application/vnd.openxmlformats-package.encrypted-package';
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Override PartName="/EncryptedPackage" ContentType="' . $encryptedContentType . '"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['_rels/.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rEncryptedPackage" Type="' . $encryptedRelationshipType . '" Target="EncryptedPackage?cipher=aes#payload"/>' . "\n" .
            '  <Relationship Id="rExternalEncryptedPackage" Type="' . $encryptedRelationshipType . '" Target="file:///tmp/review-encrypted.docx" TargetMode="External"/>' . "\n" .
            '</Relationships>',
            $parts['_rels/.rels']
        );
        $parts['EncryptedPackage'] = 'encrypted package bytes';

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $package = $document->attr('docx')['packageProvenance'];
        $summary = $package['summary'];
        $encryptedPackages = $package['encryptedPackages'];
        $encrypted = $encryptedPackages['byRelationshipId']['rEncryptedPackage'];
        $external = $encryptedPackages['byRelationshipId']['rExternalEncryptedPackage'];
        $inventory = $package['parts']['EncryptedPackage'];
        $relationshipType = $package['relationshipTypes'][$encryptedRelationshipType];

        $t->same('Imported DOCX Heading', $document->children[0]->attr('text'));
        $t->same(true, $encryptedPackages['present']);
        $t->same(2, $encryptedPackages['count']);
        $t->same(1, $encryptedPackages['existingCount']);
        $t->same(0, $encryptedPackages['missingCount']);
        $t->same(1, $encryptedPackages['externalCount']);
        $t->same(0, $encryptedPackages['allowedExternalCount']);
        $t->same(1, $encryptedPackages['unsafeExternalCount']);
        $t->same(2, $encryptedPackages['invalidCount']);
        $t->same(2, $encryptedPackages['issueCount']);
        $t->same(['EncryptedPackage'], $encryptedPackages['targetParts']);
        $t->same(['file:///tmp/review-encrypted.docx'], $encryptedPackages['externalTargets']);
        $t->same([$encryptedContentType], $encryptedPackages['contentTypes']);
        $t->same([
            'external-encrypted-package-target',
            'external-target-unsafe-scheme',
            'multiple-encrypted-package-relationships',
        ], $encryptedPackages['issueCodes']);
        $t->same(['external-target-unsafe-scheme'], $encryptedPackages['externalTargetIssueCodes']);
        $t->same('encrypted-package-bytes-blocked', $encryptedPackages['byteExposurePolicy']);
        $t->same('encrypted-package-metadata-only', $encryptedPackages['reviewPolicy']);
        $t->same(false, $encryptedPackages['canExposeBytes']);

        $t->same('EncryptedPackage?cipher=aes#payload', $encrypted['resolvedTarget']);
        $t->same('EncryptedPackage', $encrypted['targetPart']);
        $t->same('cipher=aes', $encrypted['targetQuery']);
        $t->same('payload', $encrypted['targetFragment']);
        $t->same('?cipher=aes#payload', $encrypted['targetReferenceSuffix']);
        $t->same(true, $encrypted['exists']);
        $t->same($encryptedContentType, $encrypted['contentType']);
        $t->same($encryptedContentType, $encrypted['contentTypeBase']);
        $t->same('override', $encrypted['contentTypeSource']);
        $t->same(strlen($parts['EncryptedPackage']), $encrypted['byteLength']);
        $t->same(hash('sha256', $parts['EncryptedPackage']), $encrypted['sha256']);
        $t->same(false, $encrypted['canExposeBytes']);
        $t->same('encrypted-package-bytes-blocked', $encrypted['byteExposurePolicy']);
        $t->same(['multiple-encrypted-package-relationships'], $encrypted['issues']);

        $t->same(true, $external['external']);
        $t->same(null, $external['targetPart']);
        $t->same('file', $external['externalTargetScheme']);
        $t->same(false, $external['externalTargetAllowed']);
        $t->same(['external-target-unsafe-scheme'], $external['externalTargetIssues']);
        $t->same([
            'multiple-encrypted-package-relationships',
            'external-encrypted-package-target',
            'external-target-unsafe-scheme',
        ], $external['issues']);

        $t->true(in_array('encrypted-package', $inventory['roles'], true), 'encrypted package inventory role missing');
        $t->true(in_array('root-relationship-target', $inventory['roles'], true), 'encrypted package root target role missing');
        $t->same(2, $relationshipType['count']);
        $t->same(1, $relationshipType['existingTargetCount']);
        $t->same(1, $relationshipType['externalCount']);
        $t->same(1, $relationshipType['unsafeExternalTargetCount']);
        $t->same(1, $relationshipType['targetRoleCounts']['encrypted-package'] ?? 0);

        $t->same(2, $summary['encryptedPackageCount']);
        $t->same(1, $summary['encryptedPackageExistingCount']);
        $t->same(1, $summary['encryptedPackageExternalCount']);
        $t->same(1, $summary['encryptedPackageUnsafeExternalCount']);
        $t->same(2, $summary['encryptedPackageIssueCount']);
