    'summarizes docx package part duplicate digest groups for review handoff' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $sharedXml = '<sharedReview>duplicate payload</sharedReview>';
        $binaryPayload = 'duplicate binary payload';
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Default Extension="bin" ContentType="application/octet-stream"/>' . "\n" .
            '  <Override PartName="/word/review/shared.xml" ContentType="application/vnd.example.shared+xml"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['word/_rels/document.xml.rels'] = str_replace(
            '</Relationships>',
            '  <Relationship Id="rSharedDuplicate" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/shared.xml"/>' . "\n" .
            '</Relationships>',
            $parts['word/_rels/document.xml.rels']
        );
        $parts['customXml/shared.xml'] = $sharedXml;
        $parts['word/media/shared.xml'] = $sharedXml;
        $parts['word/review/shared.xml'] = $sharedXml;
        $parts['customXml/shared.bin'] = $binaryPayload;
        $parts['customXml/shared.payload'] = $binaryPayload;

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $summary = $document->attr('docx')['packageProvenance']['summary'];
        $sharedSha256 = hash('sha256', $sharedXml);
        $binarySha256 = hash('sha256', $binaryPayload);
        $expectedSha256Values = [$binarySha256, $sharedSha256];
        sort($expectedSha256Values, SORT_STRING);
        $bySha256 = [];
        foreach ($summary['duplicatePartDigests'] as $digest) {
            $bySha256[$digest['sha256']] = $digest;
        }

        $t->same(2, $summary['duplicatePartDigestGroupCount']);
        $t->same(5, $summary['duplicatePartDigestPartCount']);
        $t->same((3 * strlen($sharedXml)) + (2 * strlen($binaryPayload)), $summary['duplicatePartDigestByteLength']);
        $t->same($expectedSha256Values, $summary['duplicatePartDigestSha256Values']);
        $t->same([
            'customXml/shared.bin',
            'customXml/shared.payload',
            'customXml/shared.xml',
            'word/media/shared.xml',
            'word/review/shared.xml',
        ], $summary['duplicatePartDigestPartNames']);

        $shared = $bySha256[$sharedSha256];
        $t->same($sharedSha256, $shared['sha256']);
        $t->same([sprintf('%08x', crc32($sharedXml))], $shared['crc32Values']);
        $t->same(3, $shared['partCount']);
        $t->same(3 * strlen($sharedXml), $shared['byteLength']);
        $t->same(['customXml', 'word/media', 'word/review'], $shared['directories']);
        $t->same(['default' => 2, 'override' => 1], $shared['contentTypeSourceCounts']);
        $t->same([
            'application/vnd.example.shared+xml' => 1,
            'application/xml' => 2,
        ], $shared['contentTypeBaseCounts']);
        $t->same(['document-relationship-target' => 1, 'package-part' => 2], $shared['roleCounts']);
        $t->same(['customXml/shared.xml', 'word/media/shared.xml', 'word/review/shared.xml'], $shared['partNames']);
        $t->same('customXml/shared.xml', $shared['largestPart']['partName']);
        $t->same('customXml', $shared['largestPart']['directory']);
        $t->same('shared.xml', $shared['largestPart']['baseName']);
        $t->same('xml', $shared['largestPart']['partExtension']);
        $t->same($sharedSha256, $shared['largestPart']['sha256']);
        $t->same('application/xml', $shared['largestPart']['contentTypeBase']);
        $t->same('default', $shared['largestPart']['contentTypeSource']);
        $t->same(['package-part'], $shared['largestPart']['roles']);

        $binary = $bySha256[$binarySha256];
        $t->same([sprintf('%08x', crc32($binaryPayload))], $binary['crc32Values']);
        $t->same(2, $binary['partCount']);
        $t->same(2 * strlen($binaryPayload), $binary['byteLength']);
        $t->same(['customXml'], $binary['directories']);
        $t->same(['default' => 1, 'missing' => 1], $binary['contentTypeSourceCounts']);
        $t->same(['(missing)' => 1, 'application/octet-stream' => 1], $binary['contentTypeBaseCounts']);
        $t->same(['package-part' => 2], $binary['roleCounts']);
        $t->same(['customXml/shared.bin', 'customXml/shared.payload'], $binary['partNames']);
        $t->same('customXml/shared.bin', $binary['largestPart']['partName']);
        $t->same('application/octet-stream', $binary['largestPart']['contentTypeBase']);
        $t->same('default', $binary['largestPart']['contentTypeSource']);
    },
    'summarizes docx package inventory byte buckets for review handoff' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['[Content_Types].xml'] = str_replace(
            '</Types>',
            '  <Default Extension="bin" ContentType="application/octet-stream"/>' . "\n" .
            '</Types>',
            $parts['[Content_Types].xml']
        );
        $parts['word/embeddings/review.bin'] = str_repeat('B', 31);
        $parts['customXml/no-type.payload'] = str_repeat('M', 17);
        $parts['customXml/empty.bin'] = '';
        $parts['word/media/full-resolution-review.png'] = str_repeat('P', 70000);

        $document = (new DocxOpenXmlReader())->readPackage($parts);
        $package = $document->attr('docx')['packageProvenance'];
        $summary = $package['summary'];
        $inventory = $package['parts'];

        $relationshipPartBytes = strlen($parts['_rels/.rels']) + strlen($parts['word/_rels/document.xml.rels']);
        $overrideBytes = strlen($parts['word/document.xml']) + strlen($parts['docProps/core.xml']);
        $missingBytes = strlen($parts['customXml/no-type.payload']);
        $defaultBytes = array_sum(array_map('strlen', $parts)) - $overrideBytes - $missingBytes;
        $packagePartBytes = strlen($parts['word/styles.xml'])
            + strlen($parts['word/numbering.xml'])
            + strlen($parts['word/embeddings/review.bin'])
            + strlen($parts['customXml/no-type.payload'])
            + strlen($parts['customXml/empty.bin'])
            + strlen($parts['word/media/full-resolution-review.png']);
        $byteBucketFor = static function (int $bytes): string {
            if ($bytes <= 0) {
                return 'empty';
            }
            if ($bytes <= 64) {
                return 'small';
            }
            if ($bytes <= 1024) {
                return 'medium';
            }
            if ($bytes <= 65536) {
                return 'large';
            }

            return 'huge';
        };
        $expectedBucketCounts = [];
        $expectedBucketByteLengths = [];
        foreach ($parts as $contents) {
            $bytes = strlen($contents);
            $bucket = $byteBucketFor($bytes);
            $expectedBucketCounts[$bucket] = ($expectedBucketCounts[$bucket] ?? 0) + 1;
            $expectedBucketByteLengths[$bucket] = ($expectedBucketByteLengths[$bucket] ?? 0) + $bytes;
        }
        $bucketOrder = ['empty' => 0, 'small' => 1, 'medium' => 2, 'large' => 3, 'huge' => 4];
        uksort(
            $expectedBucketCounts,
            static fn (string $left, string $right): int => $bucketOrder[$left] <=> $bucketOrder[$right],
        );
        uksort(
            $expectedBucketByteLengths,
            static fn (string $left, string $right): int => $bucketOrder[$left] <=> $bucketOrder[$right],
        );
        $bucketRows = [];
        foreach ($summary['partByteLengthBuckets'] as $bucketRow) {
            $bucketRows[$bucketRow['byteLengthBucket']] = $bucketRow;
        }

        $t->same(array_sum(array_map('strlen', $parts)), $summary['packageByteLength']);
        $t->same($relationshipPartBytes, $summary['relationshipPartByteLength']);
        $t->same($missingBytes, $summary['missingContentTypePartByteLength']);
        $t->same(['default' => 9, 'missing' => 1, 'override' => 2], $summary['contentTypeSourceCounts']);
        $t->same($defaultBytes, $summary['contentTypeSourceByteLengths']['default']);
        $t->same($missingBytes, $summary['contentTypeSourceByteLengths']['missing']);
        $t->same($overrideBytes, $summary['contentTypeSourceByteLengths']['override']);
        $t->same($expectedBucketCounts, $summary['partByteLengthBucketCounts']);
        $t->same($expectedBucketByteLengths, $summary['partByteLengthBucketByteLengths']);
        $t->same(5, $summary['partByteLengthBucketCount']);
        $t->same('empty', $inventory['customXml/empty.bin']['byteLengthBucket']);
        $t->same('small', $inventory['word/embeddings/review.bin']['byteLengthBucket']);
        $t->same('small', $inventory['customXml/no-type.payload']['byteLengthBucket']);
        $t->same('large', $inventory['word/document.xml']['byteLengthBucket']);
        $t->same('huge', $inventory['word/media/full-resolution-review.png']['byteLengthBucket']);
        $t->same(1, $summary['partByteLengthBucketMissingContentTypeCounts']['small']);
        $t->same(2, $summary['partByteLengthBucketRelationshipPartCounts']['medium']);
        $t->same(['default' => 2, 'missing' => 1], $bucketRows['small']['contentTypeSourceCounts']);
        $t->same(['document-relationship-target' => 1, 'package-part' => 2], $bucketRows['small']['roleCounts']);
        $t->same('customXml/empty.bin', $bucketRows['empty']['largestPart']['partName']);
        $t->same('word/document.xml', $bucketRows['large']['largestPart']['partName']);
        $t->same('word/media/full-resolution-review.png', $bucketRows['huge']['largestPart']['partName']);
        $t->same(70000, $bucketRows['huge']['largestPart']['bytes']);
        $t->same(['package-part'], $bucketRows['huge']['largestPart']['roles']);
        $t->true(in_array('word/media/full-resolution-review.png', $bucketRows['huge']['partNames'], true), 'huge bucket should include the full-resolution media part');

        $t->same(strlen($parts['[Content_Types].xml']), $summary['roleByteLengths']['content-types']);
        $t->same($relationshipPartBytes, $summary['roleByteLengths']['relationship-part']);
        $t->same(strlen($parts['_rels/.rels']), $summary['roleByteLengths']['package-relationships']);
        $t->same(strlen($parts['word/_rels/document.xml.rels']), $summary['roleByteLengths']['office-document-relationships']);
        $t->same(strlen($parts['word/document.xml']), $summary['roleByteLengths']['office-document']);
        $t->same($overrideBytes, $summary['roleByteLengths']['root-relationship-target']);
        $t->same(strlen($parts['word/media/review.png']), $summary['roleByteLengths']['document-relationship-target']);
        $t->same($packagePartBytes, $summary['roleByteLengths']['package-part']);
    },
    'classifies docx package part byte length buckets for review handoff' => static function (TestRunner $t): void {
        $parts = docx_openxml_reader_fixture_parts();
        $parts['[Content_Types].xml'] = str_replace(
