        $t->same('payload', $package['relationships'][1]['targetFragment']);
        $t->same('word/embeddings/review-package', $package['existingTargetPartDigests'][1]['partName']);
        $t->same(null, $package['existingTargetPartDigests'][1]['partExtension']);
