        $t->same('Excel.Sheet.12', $workbook['progId']);
        $t->same('_x0000_i1025', $workbook['shapeId']);
        $t->same('Content', $workbook['drawAspect']);
        $t->same('_review1', $workbook['objectId']);
        $t->same('OnCall', $workbook['updateMode']);
