        $docVarPayload = str_repeat('<w:docVar w:name="review" w:val="bucket"/>', 1700);
        $parts['word/settings.xml'] = '<?xml version="1.0" encoding="UTF-8"?>' .
            '<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' .
