/**
 * @param array<string, string> $parts
 * @return list<array{name:string, data:string}>
 */
function docx_openxml_reader_zip_parts(array $parts): array
{
    $zipParts = [];
    foreach ($parts as $name => $contents) {
        $zipParts[] = [
            'name' => $name,
            'data' => $contents,
        ];
    }

    return $zipParts;
}

function docx_openxml_reader_ntfs_timestamp_extra(int $modifiedAt, int $accessedAt, int $createdAt): string
{
    $payload = pack('V', 0)
        . pack('vv', 0x0001, 24)
        . docx_openxml_reader_ntfs_filetime($modifiedAt)
        . docx_openxml_reader_ntfs_filetime($accessedAt)
        . docx_openxml_reader_ntfs_filetime($createdAt);

    return pack('vv', 0x000a, strlen($payload)) . $payload;
}

function docx_openxml_reader_ntfs_filetime(int $timestamp): string
{
    $filetime = ($timestamp + 11644473600) * 10000000;
    $low = $filetime % 4294967296;
    $high = intdiv($filetime, 4294967296);

    return pack('VV', $low, $high);
}

/**
 * @param array<string, string> $parts
 * @param array<string, int> $compressionMethodsByName
 */
function docx_openxml_reader_zip_package_with_compression_methods(array $parts, array $compressionMethodsByName): ZipPackage
{
    $body = '';
    $central = '';
    $entryCount = 0;

    foreach ($parts as $name => $contents) {
        $method = $compressionMethodsByName[$name] ?? 8;
        $compressed = $method === 8 ? gzdeflate($contents) : $contents;
        if (!is_string($compressed)) {
            throw new RuntimeException("Unable to deflate DOCX fixture entry {$name}");
        }

        $crc32 = (int) sprintf('%u', crc32($contents));
        $offset = strlen($body);
        $body .= pack(
            'VvvvvvVVVvv',
            0x04034b50,
            20,
            0x0800,
            $method,
            0,
            0,
            $crc32,
            strlen($compressed),
            strlen($contents),
            strlen($name),
            0,
        );
        $body .= $name . $compressed;

        $central .= pack(
            'VvvvvvvVVVvvvvvVV',
            0x02014b50,
            0x0314,
            20,
            0x0800,
            $method,
            0,
            0,
            $crc32,
            strlen($compressed),
            strlen($contents),
            strlen($name),
            0,
            0,
            0,
            0,
            0,
            $offset,
        );
        $central .= $name;
        ++$entryCount;
    }

    return ZipPackage::fromString(
        $body
        . $central
        . pack('VvvvvVVv', 0x06054b50, 0, 0, $entryCount, $entryCount, strlen($central), strlen($body), 0)
    );
}

/**
 * @param array<string, string> $parts
 * @param list<array{name:string, localName?:string, data:string, method?:int, flags?:int, localExtra?:string, centralExtra?:string, comment?:string}> $rawNameEntries
 */
function docx_openxml_reader_zip_package_with_raw_name_entries(array $parts, array $rawNameEntries): ZipPackage
{
    $entries = [];
    foreach ($parts as $name => $contents) {
        $entries[] = [
            'name' => $name,
            'data' => $contents,
            'method' => 8,
            'flags' => 0x0800,
        ];
    }
    foreach ($rawNameEntries as $entry) {
        $entries[] = $entry;
    }

    return ZipPackage::fromString(docx_openxml_reader_raw_zip_bytes($entries));
}

/**
 * @param list<array{name:string, localName?:string, data:string, method?:int, flags?:int, localExtra?:string, centralExtra?:string, comment?:string}> $entries
 */
function docx_openxml_reader_raw_zip_bytes(array $entries): string
{
    $body = '';
    $central = '';
    $entryCount = 0;

    foreach ($entries as $entry) {
        $name = $entry['name'];
        $localName = $entry['localName'] ?? $name;
        $contents = $entry['data'];
        $method = $entry['method'] ?? 8;
        $flags = $entry['flags'] ?? 0x0800;
        $localExtra = $entry['localExtra'] ?? '';
        $centralExtra = $entry['centralExtra'] ?? $localExtra;
        $comment = $entry['comment'] ?? '';
        $compressed = match ($method) {
            0 => $contents,
            8 => gzdeflate($contents),
            default => $contents,
        };
        if (!is_string($compressed)) {
            throw new RuntimeException("Unable to deflate DOCX fixture entry {$name}");
        }

        $crc32 = (int) sprintf('%u', crc32($contents));
        $offset = strlen($body);
        $body .= pack(
            'VvvvvvVVVvv',
            0x04034b50,
            20,
            $flags,
            $method,
            0,
            0,
            $crc32,
            strlen($compressed),
            strlen($contents),
            strlen($localName),
            strlen($localExtra),
        );
        $body .= $localName . $localExtra . $compressed;

        $central .= pack(
            'VvvvvvvVVVvvvvvVV',
            0x02014b50,
            0x0314,
            20,
            $flags,
            $method,
            0,
            0,
            $crc32,
            strlen($compressed),
            strlen($contents),
            strlen($name),
            strlen($centralExtra),
            strlen($comment),
            0,
            0,
            0,
            $offset,
        );
        $central .= $name . $centralExtra . $comment;
        ++$entryCount;
    }

    return $body
        . $central
        . pack('VvvvvVVv', 0x06054b50, 0, 0, $entryCount, $entryCount, strlen($central), strlen($body), 0);
}

function docx_openxml_reader_unicode_extra(int $id, string $rawName, string $unicodeName): string
{
    $payload = "\x01" . pack('V', (int) sprintf('%u', crc32($rawName))) . $unicodeName;

    return pack('vv', $id, strlen($payload)) . $payload;
}

/**
 * @param array<string, string> $parts
 */
function docx_openxml_reader_zip_package(array $parts): ZipPackage
{
    return ZipPackage::fromParts(docx_openxml_reader_zip_parts($parts));
}

/**
 * @param list<array{name:string, data?:string, compressionMethod?:int, descriptor?:bool, descriptorSignature?:bool}> $parts
 */
function docx_openxml_reader_data_descriptor_zip(array $parts): string
{
    $body = '';
    $central = '';

    foreach ($parts as $part) {
        $name = $part['name'];
        $data = $part['data'] ?? '';
        $method = $part['compressionMethod'] ?? ($data === '' || str_ends_with($name, '/') ? 0 : 8);
        $compressed = match ($method) {
            0 => $data,
            8 => gzdeflate($data),
            default => throw new RuntimeException("Unsupported fixture compression method {$method}"),
        };
        if (!is_string($compressed)) {
            throw new RuntimeException("Unable to deflate fixture ZIP entry {$name}");
        }

        $usesDescriptor = ($part['descriptor'] ?? false) === true;
        $flags = 0x0800 | ($usesDescriptor ? 0x0008 : 0);
        $crc32 = (int) sprintf('%u', crc32($data));
        $compressedSize = strlen($compressed);
        $uncompressedSize = strlen($data);
        $localHeaderOffset = strlen($body);
        $localCrc32 = $usesDescriptor ? 0 : $crc32;
        $localCompressedSize = $usesDescriptor ? 0 : $compressedSize;
        $localUncompressedSize = $usesDescriptor ? 0 : $uncompressedSize;

        $body .= pack(
            'VvvvvvVVVvv',
            0x04034b50,
            20,
            $flags,
            $method,
            0,
            0,
            $localCrc32,
            $localCompressedSize,
            $localUncompressedSize,
            strlen($name),
            0
        );
        $body .= $name . $compressed;
        if ($usesDescriptor) {
            if (($part['descriptorSignature'] ?? true) === true) {
                $body .= "PK\x07\x08";
            }
            $body .= pack('VVV', $crc32, $compressedSize, $uncompressedSize);
        }

        $central .= pack(
            'VvvvvvvVVVvvvvvVV',
            0x02014b50,
            0x0314,
            20,
            $flags,
            $method,
            0,
            0,
            $crc32,
            $compressedSize,
            $uncompressedSize,
            strlen($name),
            0,
            0,
            0,
            0,
            str_ends_with($name, '/') ? 0x10 : 0,
            $localHeaderOffset
        );
        $central .= $name;
    }

    $centralDirectoryOffset = strlen($body);

    return $body
        . $central
        . pack('VvvvvVVv', 0x06054b50, 0, 0, count($parts), count($parts), strlen($central), $centralDirectoryOffset, 0);
}

/**
 * @param array<string, string> $parts
 */
function docx_openxml_reader_temp_docx(array $parts): string
{
    $path = tempnam(sys_get_temp_dir(), 'pandoc-docx-');
    if ($path === false) {
        throw new RuntimeException('Unable to allocate temporary DOCX path');
    }

    $written = file_put_contents($path, ZipPackage::build(docx_openxml_reader_zip_parts($parts)));
    if ($written === false) {
        throw new RuntimeException('Unable to write temporary DOCX package');
    }

    return $path;
}
